const SERVICE_KEY = "W-XqM4UFSNyl6jOFBUjc6A";
const vars = "T1H,REH,SKY,PTY,WSD"; // 여러 요소 콤마로

// tmfc, tmef 자동 생성 함수
function getAutoTmfcTmef() {
  // 발표시각(기상청 단기예보 8회: 02, 05, 08, 11, 14, 17, 20, 23)
  const forecastHours = [2, 5, 8, 11, 14, 17, 20, 23];
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const dd = String(now.getDate()).padStart(2, "0");
  const HH = now.getHours();

  // 가장 가까운 과거 발표시각 찾기
  let baseHour = forecastHours[0];
  for (let i = 0; i < forecastHours.length; i++) {
    if (HH >= forecastHours[i]) baseHour = forecastHours[i];
  }
  const baseTime = String(baseHour).padStart(2, "0") + "00";
  const tmfc = `${yyyy}${mm}${dd}${baseTime}`;

  // 예보시각(tmef): 지금 시각 + 1시간 (필요에 따라 조정)
  const tmefDate = new Date(now.getTime() + 60 * 60 * 1000);
  const tmefyyyy = tmefDate.getFullYear();
  const tmefmm = String(tmefDate.getMonth() + 1).padStart(2, "0");
  const tmefdd = String(tmefDate.getDate()).padStart(2, "0");
  const tmefHH = String(tmefDate.getHours()).padStart(2, "0");
  const tmef = `${tmefyyyy}${tmefmm}${tmefdd}${tmefHH}`;

  return { tmfc, tmef };
}

export async function fetchWeatherData() {
  const { tmfc, tmef } = getAutoTmfcTmef();

  const url = `https://apihub.kma.go.kr/api/typ01/cgi-bin/url/nph-dfs_vsrt_grd?tmfc=${tmfc}&tmef=${tmef}&vars=${vars}&authKey=${SERVICE_KEY}`;
  const res = await fetch(url);

  // 응답이 JSON이 아닐 수 있으니 먼저 .text()로 확인
  const text = await res.text();
  let data;
  try {
    data = JSON.parse(text); // 가능하면 JSON 파싱
  } catch (e) {
    data = text; // 안되면 text 그대로 반환
  }

  return data; // 응답 구조는 실제 명세서/데이터 보고 파싱 필요
}
